-- Local fictitious fixtures only; all changes roll back.
begin;
select extensions.no_plan();
create temp table tt_ctx as select w.id w,w.owner_id u,(select id from public.schools where workspace_id=w.id and deleted_at is null limit 1) school,(select id from public.subjects where workspace_id=w.id and deleted_at is null limit 1) subject,gen_random_uuid() y,gen_random_uuid() y2,gen_random_uuid() cls,gen_random_uuid() cls2,gen_random_uuid() cs,gen_random_uuid() cs2,gen_random_uuid() ta,gen_random_uuid() ta2,gen_random_uuid() v,gen_random_uuid() v2,gen_random_uuid() s,gen_random_uuid() s2,null::uuid lesson,null::uuid cloned
from public.workspaces w where w.owner_id='11111111-1111-4111-8111-111111111111' limit 1;
grant select,update on tt_ctx to authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
set local role authenticated;
insert into public.school_years(id,workspace_id,label,starts_on,ends_on) select y,w,'Orario fittizio 2040','2040-09-01','2041-08-31' from tt_ctx;
insert into public.school_years(id,workspace_id,label,starts_on,ends_on) select y2,w,'Orario fittizio 2041','2041-09-01','2042-08-31' from tt_ctx;
insert into public.classes(id,workspace_id,school_id,school_year_id,name) select cls,w,school,y,'1 B orario fittizio' from tt_ctx;
insert into public.classes(id,workspace_id,school_id,school_year_id,name) select cls2,w,school,y2,'2 B orario fittizio' from tt_ctx;
insert into public.class_subjects(id,workspace_id,class_id,subject_id) select cs,w,cls,subject from tt_ctx;
insert into public.class_subjects(id,workspace_id,class_id,subject_id) select cs2,w,cls2,subject from tt_ctx;
insert into public.teaching_assignments(id,workspace_id,class_subject_id,class_id,teacher_id) select ta,w,cs,cls,u from tt_ctx;
insert into public.teaching_assignments(id,workspace_id,class_subject_id,class_id,teacher_id) select ta2,w,cs2,cls2,u from tt_ctx;
insert into public.timetable_versions(id,workspace_id,school_year_id,teacher_id,name,kind,valid_from,valid_to) select v,w,y,u,'Provvisorio fittizio','provisional','2040-09-01','2041-08-31' from tt_ctx;
select extensions.is((select count(*) from public.timetable_versions where id=(select v from tt_ctx)),1::bigint,'Owner creates draft provisional');
select extensions.throws_ok($q$select public.activate_timetable(v,1) from tt_ctx$q$,'23514',null,'Empty timetable cannot activate');
insert into public.timetable_slots(id,workspace_id,timetable_version_id,teaching_assignment_id,weekday,starts_at,ends_at) select s,w,v,ta,1,'08:00','09:00' from tt_ctx;
select extensions.throws_ok($q$insert into public.timetable_slots(workspace_id,timetable_version_id,teaching_assignment_id,weekday,starts_at,ends_at) select w,v,ta,1,'08:30','09:30' from tt_ctx$q$,'23P01',null,'Overlapping slots rejected');
select extensions.throws_ok($q$insert into public.timetable_slots(workspace_id,timetable_version_id,teaching_assignment_id,weekday,starts_at,ends_at) select w,v,ta2,2,'08:00','09:00' from tt_ctx$q$,'23514',null,'Wrong school year assignment rejected');
select extensions.throws_ok($q$insert into public.timetable_slots(workspace_id,timetable_version_id,teaching_assignment_id,weekday,starts_at,ends_at) select w,v,ta,1,'09:00','08:00' from tt_ctx$q$,'23514',null,'Invalid time interval rejected');
insert into public.timetable_slots(id,workspace_id,timetable_version_id,teaching_assignment_id,weekday,starts_at,ends_at,kind) select s2,w,v,ta,1,'09:00','10:00','laboratory' from tt_ctx;
select extensions.lives_ok($q$update public.timetable_slots set notes='Modificato fittizio',version=version+1 where id=(select s2 from tt_ctx)$q$,'Draft slot editable');
select extensions.throws_ok($q$update public.timetable_slots set notes='Stale',version=1 where id=(select s2 from tt_ctx)$q$,'40001',null,'Stale edit rejected');
select extensions.lives_ok($q$select public.activate_timetable(v,1) from tt_ctx$q$,'Activate provisional online RPC');
select extensions.is((select count(*) from public.lessons where teaching_assignment_id=(select ta from tt_ctx)),0::bigint,'Activation never creates lessons');
select extensions.throws_ok($q$update public.timetable_slots set notes='Unsafe',version=version+1 where id=(select s from tt_ctx)$q$,'23514',null,'Published model immutable; exceptions or new version required');
select extensions.throws_ok($q$select public.register_timetable_lesson(s,'2040-09-04') from tt_ctx$q$,'23514',null,'Wrong weekday rejected');
-- 2040-09-03 is Monday.
insert into public.timetable_exceptions(workspace_id,timetable_version_id,slot_id,occurs_on,kind) select w,v,s,'2040-09-03','cancelled' from tt_ctx;
select extensions.throws_ok($q$select public.register_timetable_lesson(s,'2040-09-03') from tt_ctx$q$,'23514',null,'Cancelled lesson cannot create activity');
select extensions.is((select count(*) from public.lessons where teaching_assignment_id=(select ta from tt_ctx)),0::bigint,'Cancellation preserves empty actual register');
insert into public.timetable_exceptions(workspace_id,timetable_version_id,slot_id,occurs_on,kind,room) select w,v,s2,'2040-09-03','room','Laboratorio fittizio' from tt_ctx;
select extensions.throws_ok($q$insert into public.timetable_exceptions(workspace_id,timetable_version_id,occurs_on,kind,teaching_assignment_id,starts_at,ends_at) select w,v,'2040-09-03','additional',ta,'09:30','10:30' from tt_ctx$q$,'23P01',null,'Effective day rejects overlap with room variation');
insert into public.timetable_exceptions(workspace_id,timetable_version_id,occurs_on,kind,teaching_assignment_id,starts_at,ends_at) select w,v,'2040-09-03','additional',ta,'11:00','12:00' from tt_ctx;
select extensions.throws_ok($q$insert into public.timetable_exceptions(workspace_id,timetable_version_id,occurs_on,kind,teaching_assignment_id,starts_at) select w,v,'2040-09-03','additional',ta,'14:00' from tt_ctx$q$,'23514',null,'Both exception time endpoints required');
insert into public.timetable_exceptions(workspace_id,timetable_version_id,occurs_on,kind,teaching_assignment_id,starts_at,ends_at) select w,v,'2040-09-03','additional',ta,'08:00','09:00' from tt_ctx;
select extensions.throws_ok($q$update public.timetable_exceptions set deleted_at=now(),version=version+1 where slot_id=(select s from tt_ctx) and occurs_on='2040-09-03'$q$,'23P01',null,'Removing cancellation cannot restore an overlapping lesson');
update tt_ctx set lesson=public.register_timetable_lesson(s2,'2040-09-03');
select extensions.is((select public.register_timetable_lesson(s2,'2040-09-03') from tt_ctx),(select lesson from tt_ctx),'Retry reopens same lesson');
select extensions.is((select count(*) from public.lessons where teaching_assignment_id=(select ta from tt_ctx)),1::bigint,'No duplicate canonical lesson');
select extensions.is((select starts_at at time zone 'Europe/Rome' from public.lessons where id=(select lesson from tt_ctx)),'2040-09-03 09:00'::timestamp,'Rome local time round trip including DST');
select extensions.throws_ok($q$update public.timetable_exceptions set kind='cancelled',version=version+1 where slot_id=(select s2 from tt_ctx) and occurs_on='2040-09-03'$q$,'23514',null,'Registered lesson history preserved');
select extensions.throws_ok($q$insert into public.lessons(workspace_id,teaching_assignment_id,starts_at,ends_at,title,timetable_occurrence_id,timetable_occurs_on) select w,ta,'2040-09-10 20:00+02','2040-09-10 21:00+02','Fittizio',s,'2040-09-10' from tt_ctx$q$,'23514',null,'Cannot forge timetable provenance with wrong time');
insert into public.timetable_versions(id,workspace_id,school_year_id,teacher_id,name,kind,valid_from,valid_to) select v2,w,y,u,'Definitivo fittizio','definitive','2040-10-01','2041-08-31' from tt_ctx;
insert into public.timetable_slots(workspace_id,timetable_version_id,teaching_assignment_id,weekday,starts_at,ends_at) select w,v2,ta,2,'08:00','10:00' from tt_ctx;
select extensions.throws_ok($q$select public.activate_timetable(v2,1) from tt_ctx$q$,'23P01',null,'Active versions cannot overlap');
select extensions.lives_ok($q$select public.activate_timetable(v2,1,v,2) from tt_ctx$q$,'Explicit replacement closes previous period atomically');
select extensions.is((select valid_to from public.timetable_versions where id=(select v from tt_ctx)),'2040-09-30'::date,'Previous version ends day before future effective date');
select extensions.is((select count(*) from public.lessons where id=(select lesson from tt_ctx)),1::bigint,'Future version leaves registered lesson intact');
select extensions.throws_ok($q$select public.duplicate_timetable(v,'Nuovo anno fittizio',y2,u) from tt_ctx$q$,'23514',null,'Year copy requires confirmed mapping');
update tt_ctx set cloned=public.duplicate_timetable(v,'Nuovo anno fittizio',y2,u,jsonb_build_object(ta::text,ta2));
select extensions.is((select status from public.timetable_versions where id=(select cloned from tt_ctx)),'draft','Year copy remains draft');
select extensions.is((select count(*) from public.timetable_exceptions where timetable_version_id=(select cloned from tt_ctx)),0::bigint,'Year copy excludes daily exceptions');
select extensions.is((select count(*) from public.timetable_slots where timetable_version_id=(select cloned from tt_ctx) and teaching_assignment_id=(select ta2 from tt_ctx)),2::bigint,'Year copy remaps classes and confirmed assignments');
select extensions.ok(not has_function_privilege('anon','public.activate_timetable(uuid,bigint,uuid,bigint)','EXECUTE'),'Anon activation denied');
select extensions.ok(not has_function_privilege('anon','public.register_timetable_lesson(uuid,date)','EXECUTE'),'Anon register denied');
select extensions.ok(not has_table_privilege('authenticated','public.timetable_versions','DELETE'),'Hard delete denied');
reset role;
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',true);
set local role authenticated;
select extensions.is((select count(*) from public.timetable_versions where workspace_id=(select w from tt_ctx)),0::bigint,'Other workspace cannot see versions');
select extensions.is((select count(*) from public.timetable_slots where workspace_id=(select w from tt_ctx)),0::bigint,'Other workspace cannot see slots');
select extensions.is((select count(*) from public.timetable_exceptions where workspace_id=(select w from tt_ctx)),0::bigint,'Other workspace cannot see exceptions');
select extensions.throws_ok($q$select public.register_timetable_lesson(s2,'2040-09-03') from tt_ctx$q$,'42501',null,'Other workspace RPC denied');
reset role;
insert into public.workspace_members(workspace_id,user_id,role) select w,'22222222-2222-4222-8222-222222222222','viewer' from tt_ctx;
set local role authenticated;
select extensions.is((select count(*) from public.timetable_versions where workspace_id=(select w from tt_ctx)),0::bigint,'Viewer cannot read teacher timetable');
select extensions.throws_ok($q$insert into public.timetable_versions(workspace_id,school_year_id,teacher_id,name,kind,valid_from) select w,y,'22222222-2222-4222-8222-222222222222','Viewer fittizio','provisional','2040-09-01' from tt_ctx$q$,'42501',null,'Viewer cannot create timetable');
reset role;
update public.workspace_members set role='teacher' where workspace_id=(select w from tt_ctx) and user_id='22222222-2222-4222-8222-222222222222';
set local role authenticated;
select extensions.is((select count(*) from public.timetable_versions where workspace_id=(select w from tt_ctx)),0::bigint,'Teacher cannot read another teacher timetable in same workspace');
select extensions.throws_ok($q$select public.activate_timetable(v2,2) from tt_ctx$q$,'42501',null,'Teacher cannot activate colleague version');
insert into public.timetable_versions(workspace_id,school_year_id,teacher_id,name,kind,valid_from) select w,y,'22222222-2222-4222-8222-222222222222','Docente fittizio','provisional','2040-09-01' from tt_ctx;
select extensions.is((select count(*) from public.timetable_versions where workspace_id=(select w from tt_ctx)),1::bigint,'Teacher can create and read own draft');
select extensions.throws_ok($q$insert into public.timetable_slots(workspace_id,timetable_version_id,teaching_assignment_id,weekday,starts_at,ends_at) select w,(select id from public.timetable_versions where teacher_id=auth.uid() and workspace_id=tt_ctx.w),ta,1,'08:00','09:00' from tt_ctx$q$,'23514',null,'Teacher cannot use colleague assignment');
reset role;
update public.workspace_members set role='admin' where workspace_id=(select w from tt_ctx) and user_id='22222222-2222-4222-8222-222222222222';
set local role authenticated;
select extensions.ok((select count(*)>1 from public.timetable_versions where workspace_id=(select w from tt_ctx)),'Admin reads authorized workspace teacher versions');
reset role;
update public.workspace_members set revoked_at=now() where workspace_id=(select w from tt_ctx) and user_id='22222222-2222-4222-8222-222222222222';
set local role authenticated;
select extensions.is((select count(*) from public.timetable_versions where workspace_id=(select w from tt_ctx)),0::bigint,'Revocation removes timetable access');
reset role;
select * from extensions.finish();
rollback;
